import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";

const root = process.cwd();
const pointerPath = "data/production/semantic-decision-projection/active.json";
const pointerRaw = await readFile(path.join(root, pointerPath), "utf8");
const pointer = JSON.parse(pointerRaw);
if (pointer.releaseFile !== "data/production/semantic-decision-projection/releases/SDP-V2-ALL-ACTIVE-CATALOGS-TR-v4.0/release.json") {
  throw new Error("P_MATERIALITY_BUNDLE_RELEASE_NOT_ADMITTED");
}
const releaseRaw = await readFile(path.join(root, pointer.releaseFile), "utf8");
const destination = path.join(root, "features/semantic-decision-projection/v2/activeWaveBundle.generated.ts");
const source = `// Generated by scripts/generate-p-materiality-runtime-bundle.mjs. Do not edit.\n`+
  `export const ACTIVE_P_MATERIALITY_POINTER_PATH = ${JSON.stringify(pointerPath)} as const;\n`+
  `export const ACTIVE_P_MATERIALITY_RELEASE_PATH = ${JSON.stringify(pointer.releaseFile)} as const;\n`+
  `export const ACTIVE_P_MATERIALITY_POINTER_RAW = ${JSON.stringify(pointerRaw)} as const;\n`+
  `export const ACTIVE_P_MATERIALITY_RELEASE_RAW = ${JSON.stringify(releaseRaw)} as const;\n`;
await mkdir(path.dirname(destination), { recursive: true });
await writeFile(destination, source);
console.log(JSON.stringify({ event: "p_materiality_runtime_bundle_generated", destination, releaseId: pointer.releaseId, releaseSha256: pointer.releaseSha256, bytes: Buffer.byteLength(releaseRaw) }));
